//  Created by Kévin Naudin on 2026-06-03.
//
//  Minimal `.npy` reader for parity fixtures generated by
//  `tools/granite_parity/dump_granite_fixtures.py`. Supports C-order
//  little-endian float32 ('<f4') and int32 ('<i4') arrays - enough for the
//  Granite-Speech port fixtures.
//

import Foundation
import MLX

enum Numpy {
    struct Array {
        let shape: [Int]
        let descr: String
        let raw: Data // payload after header
    }

    /// Locate the fixtures root: `$GRANITE_FIXTURES` or, by default, the
    /// repo-relative `tools/granite_parity/fixtures` (resolved from this file).
    static var fixturesRoot: URL {
        if let env = ProcessInfo.processInfo.environment["GRANITE_FIXTURES"] {
            return URL(fileURLWithPath: env, isDirectory: true)
        }
        // this file: <repo>/libs/speech-swift-vendored/Tests/GraniteSpeechTests/NumpyFixtures.swift
        // -> 5 components up (file + 4 dirs) reaches the repo root.
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0 ..< 5 { url.deleteLastPathComponent() } // -> repo root
        return url
            .appendingPathComponent("tools/granite_parity/fixtures", isDirectory: true)
    }

    static func load(_ relativePath: String) throws -> Array {
        let url = fixturesRoot.appendingPathComponent(relativePath)
        let data = try Data(contentsOf: url)
        return try parse(data)
    }

    static func parse(_ data: Data) throws -> Array {
        // magic: \x93NUMPY, then major/minor (1 byte each)
        guard data.count > 10,
              data[0] == 0x93,
              data[1...5].elementsEqual("NUMPY".utf8)
        else { throw Err.bad("not a .npy file") }

        let major = data[6]
        let headerLen: Int
        let headerStart: Int
        if major == 1 {
            headerLen = Int(data[8]) | (Int(data[9]) << 8)
            headerStart = 10
        } else {
            headerLen = Int(data[8]) | (Int(data[9]) << 8)
                | (Int(data[10]) << 16) | (Int(data[11]) << 24)
            headerStart = 12
        }
        let headerData = data.subdata(in: headerStart ..< (headerStart + headerLen))
        guard let header = String(data: headerData, encoding: .ascii) else {
            throw Err.bad("non-ascii header")
        }

        let descr = try matchQuoted(header, key: "descr")
        let shape = try matchShape(header)
        let payloadStart = headerStart + headerLen
        let raw = data.subdata(in: payloadStart ..< data.count)
        return Array(shape: shape, descr: descr, raw: raw)
    }

    private static func matchQuoted(_ s: String, key: String) throws -> String {
        // ... 'descr': '<f4' ...
        guard let kr = s.range(of: "'\(key)'") else { throw Err.bad("no \(key)") }
        let after = s[kr.upperBound...]
        guard let open = after.range(of: "'") else { throw Err.bad("no value for \(key)") }
        let rest = after[open.upperBound...]
        guard let close = rest.range(of: "'") else { throw Err.bad("unterminated \(key)") }
        return String(rest[..<close.lowerBound])
    }

    private static func matchShape(_ s: String) throws -> [Int] {
        guard let kr = s.range(of: "'shape'") else { throw Err.bad("no shape") }
        let after = s[kr.upperBound...]
        guard let open = after.range(of: "("), let close = after.range(of: ")") else {
            throw Err.bad("no shape tuple")
        }
        let inner = after[open.upperBound ..< close.lowerBound]
        return inner.split(separator: ",")
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }
            .compactMap { Int($0) }
    }

    enum Err: Error { case bad(String) }
}

extension Numpy.Array {
    var count: Int { shape.reduce(1, *) }

    func floats() -> [Float] {
        precondition(descr == "<f4", "expected float32, got \(descr)")
        return raw.withUnsafeBytes { Swift.Array($0.bindMemory(to: Float.self).prefix(count)) }
    }

    func int32s() -> [Int32] {
        precondition(descr == "<i4", "expected int32, got \(descr)")
        return raw.withUnsafeBytes { Swift.Array($0.bindMemory(to: Int32.self).prefix(count)) }
    }

    /// Load into an MLXArray with the recorded shape (float32 only).
    func mlx() -> MLXArray {
        MLXArray(floats()).reshaped(shape)
    }
}
